"""Ragas-backed evaluator for generation quality metrics.

Ragas needs more information than the base retrieval-evaluation contract
(``retrieved_ids`` and ``golden_ids``).  When it is available, callers can
place the following values in the optional ``trace`` mapping:

* ``answer`` (or ``response``): the answer generated by the LLM;
* ``contexts`` (or ``retrieved_contexts``): text of the retrieved chunks;
* ``reference`` (or ``ground_truth``): the expected answer.

The ID lists remain useful fallbacks.  This keeps the Phase-B evaluator API
compatible while allowing the Phase-H runner to provide the richer data that
Ragas needs.
"""

from __future__ import annotations

import importlib
from collections.abc import Mapping, Sequence
from typing import Any

from libs.evaluator.base_evaluator import BaseEvaluator
from libs.evaluator.evaluator_factory import EvaluatorFactory


class RagasEvaluator(BaseEvaluator):
    """Evaluate answer faithfulness, relevancy, and context precision via Ragas."""

    name = "ragas"
    _METRIC_NAMES = ("faithfulness", "answer_relevancy", "context_precision")

    def evaluate(
        self,
        query: str,
        retrieved_ids: list[str],
        golden_ids: list[str],
        trace: Any = None,
    ) -> dict[str, float]:
        """Run the three supported Ragas metrics for one query.

        Ragas and its optional provider integrations are imported here rather
        than at module import time.  Therefore a project using only the light
        weight ``custom`` evaluator does not need Ragas installed.
        """
        evaluate_fn, metrics = self._load_ragas()
        dataset = self._build_dataset(query, retrieved_ids, golden_ids, trace)
        result = evaluate_fn(dataset=dataset, metrics=metrics)
        return self._normalise_scores(result)

    @classmethod
    def _load_ragas(cls) -> tuple[Any, list[Any]]:
        """Load Ragas lazily and give users an actionable dependency error."""
        try:
            ragas = importlib.import_module("ragas")
            metrics_module = importlib.import_module("ragas.metrics")
        except (ImportError, ModuleNotFoundError) as exc:
            raise ImportError(
                "RagasEvaluator 需要可用的 ragas 依赖。请执行 "
                "`pip install ragas`，并安装该版本 Ragas 所需的可选依赖。"
            ) from exc

        evaluate_fn = getattr(ragas, "evaluate", None)
        if not callable(evaluate_fn):
            raise ImportError("已安装的 ragas 未提供 evaluate()；请升级或重新安装 ragas。")

        metrics: list[Any] = []
        for metric_name in cls._METRIC_NAMES:
            metric = getattr(metrics_module, metric_name, None)
            if metric is None:
                raise ImportError(
                    f"已安装的 ragas 不支持指标 '{metric_name}'；请使用兼容的 ragas 版本。"
                )
            metrics.append(metric)
        return evaluate_fn, metrics

    @staticmethod
    def _build_dataset(
        query: str,
        retrieved_ids: list[str],
        golden_ids: list[str],
        trace: Any,
    ) -> Any:
        """Create the one-row dataset expected by the classic Ragas API."""
        try:
            from datasets import Dataset
        except ImportError as exc:
            raise ImportError(
                "RagasEvaluator 需要 datasets 依赖。请执行 `pip install datasets`。"
            ) from exc

        details = trace if isinstance(trace, Mapping) else {}
        contexts = details.get("contexts", details.get("retrieved_contexts", retrieved_ids))
        if isinstance(contexts, str) or not isinstance(contexts, Sequence):
            contexts = [contexts]

        answer = details.get("answer", details.get("response", " ".join(retrieved_ids)))
        reference = details.get(
            "reference", details.get("ground_truth", " ".join(golden_ids))
        )
        return Dataset.from_dict(
            {
                "question": [str(query)],
                "answer": [str(answer)],
                "contexts": [[str(context) for context in contexts]],
                "ground_truth": [str(reference)],
            }
        )

    @classmethod
    def _normalise_scores(cls, result: Any) -> dict[str, float]:
        """Convert Ragas result variants into the project's plain metric dict."""
        scores: Mapping[str, Any] | None = result if isinstance(result, Mapping) else None

        if scores is None and hasattr(result, "scores"):
            rows = result.scores
            if isinstance(rows, Sequence) and rows and isinstance(rows[0], Mapping):
                scores = rows[0]

        if scores is None and hasattr(result, "to_pandas"):
            frame = result.to_pandas()
            if not frame.empty:
                scores = frame.iloc[0].to_dict()

        if scores is None:
            raise TypeError("Ragas 返回了无法识别的评估结果格式。")

        missing = [name for name in cls._METRIC_NAMES if name not in scores]
        if missing:
            raise ValueError(f"Ragas 评估结果缺少指标: {', '.join(missing)}")
        return {name: float(scores[name]) for name in cls._METRIC_NAMES}


EvaluatorFactory.register("ragas", RagasEvaluator)
